  const absaetze = String(a.text || '').split(/\n\s*\n/)
    .map(p => `<p style="margin:0 0 14px">${p.replace(/\n/g, '<br>')}</p>`).join('');

  const html = `
<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#1a2430;line-height:1.65;max-width:620px">
  <p style="margin:0 0 14px">Guten Tag ${l.name || ''},</p>
