/* Tagesbericht an die Verkaufsleitung. */
const d    = $input.first().json;
const cfg  = d.cfg;
const alle = d.alle || [];
const tag  = 24 * 60 * 60 * 1000;
const jetzt = Date.now();

const seit = (r, t) => {
  const x = new Date(r.eingang || 0).getTime();
  return !isNaN(x) && (jetzt - x) < t * tag;
};

const neu24     = alle.filter(r => seit(r, 1));
const neu7      = alle.filter(r => seit(r, 7));
const offen     = alle.filter(r => ['neu','kontaktiert','nachgefasst'].includes(String(r.status||'').toLowerCase()));
const termine   = alle.filter(r => r.termin_bestaetigt && new Date(r.termin || 0).getTime() > jetzt);
const antworten = alle.filter(r => String(r.status||'').toLowerCase() === 'geantwortet');

const heiss = offen.filter(r => Number(r.score || 0) >= 70)
                   .sort((a, b) => Number(b.score||0) - Number(a.score||0))
                   .slice(0, 8);

const zeilen = heiss.map(r => `
  <tr>
    <td style="padding:7px 10px;border-bottom:1px solid #e3e8ef"><b>${r.score}</b></td>
    <td style="padding:7px 10px;border-bottom:1px solid #e3e8ef">${r.name || r.email}</td>
    <td style="padding:7px 10px;border-bottom:1px solid #e3e8ef">${r.fahrzeug || '—'}</td>
    <td style="padding:7px 10px;border-bottom:1px solid #e3e8ef">${r.verkaeufer || '—'}</td>
    <td style="padding:7px 10px;border-bottom:1px solid #e3e8ef;color:#5b6b80">${String(r.eingang||'').substring(0,10)}</td>
  </tr>`).join('') || '<tr><td colspan="5" style="padding:10px;color:#5b6b80">Aktuell keine Leads über 70 Punkten.</td></tr>';

const kachel = (wert, text) => `
  <td style="padding:14px 16px;background:#f5f7fa;border-radius:10px;text-align:center;width:20%">
    <div style="font-size:26px;font-weight:700;color:#142b47">${wert}</div>
    <div style="font-size:12px;color:#5b6b80;letter-spacing:.04em;text-transform:uppercase;margin-top:4px">${text}</div>
  </td>`;

const html = `
<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#1a2430;line-height:1.6;max-width:700px">
  <p style="margin:0 0 4px;font-size:13px;color:#5b6b80">${cfg.autohaus} · Tagesbericht</p>
  <h2 style="margin:0 0 20px;font-size:21px;color:#142b47">Stand vom ${new Date().toLocaleDateString('de-DE')}</h2>
  <table cellspacing="8" style="border-collapse:separate;width:100%">
    <tr>
      ${kachel(neu24.length, 'Neu 24 h')}
      ${kachel(neu7.length, 'Neu 7 Tage')}
      ${kachel(offen.length, 'Offen')}
      ${kachel(termine.length, 'Termine')}
      ${kachel(antworten.length, 'Antworten')}
    </tr>
  </table>
  <p style="margin:26px 0 10px"><b>Die heißesten offenen Leads</b></p>
  <table cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;font-size:14px">
    <tr style="background:#142b47;color:#fff">
      <th style="padding:8px 10px;text-align:left">Score</th>
      <th style="padding:8px 10px;text-align:left">Interessent</th>
      <th style="padding:8px 10px;text-align:left">Fahrzeug</th>
      <th style="padding:8px 10px;text-align:left">Verkäufer</th>
      <th style="padding:8px 10px;text-align:left">Eingang</th>
    </tr>
    ${zeilen}
  </table>
  <p style="margin:24px 0 0;font-size:13px;color:#5b6b80">
    Heute automatisch bearbeitet: ${d.aufgaben} Vorgänge (Nachfassen, Erinnerungen, Archivierung).
  </p>
</div>`;

return [{ json: {
  mailAn:      cfg.verkaufsleitung,
  mailBetreff: 'Tagesbericht ' + cfg.autohaus + ' — ' + neu24.length + ' neue Anfragen',
  mailHtml:    html
}}];

/* Das Dashboard fragt an. Schluessel pruefen und die passende
   Abfrage bauen. Der Abfragetext kommt IMMER von hier, nie vom
   Aufrufer — Werte werden ausschliesslich als Parameter uebergeben. */
const d   = $json;
const cfg = d.cfg;

if (!cfg.dashboardToken || d.token !== cfg.dashboardToken) {
  return [{ json: { erlaubt: false, fehler: 'Zugriff verweigert', query: 'select 1 where false', sqlWerte: [] } }];
}

const dat = d.daten || {};
const A = {

  kennzahlen: {
    query: 'select * from kennzahlen',
    werte: []
  },

  leads: {
    query: `select lead_id, eingang, quelle, name, email, telefon, nachricht, fahrzeug,
                   fahrzeug_id, kaufabsicht, inzahlungnahme, inzahlung_fahrzeug, dringlichkeit,
                   finanzierung, score, zusammenfassung, verkaeufer, verkaeufer_email, status,
                   sequenz, nachfass_stufe, letzter_kontakt, naechster_schritt, termin,
                   termin_bestaetigt, notiz
            from leads
            where ($1 = '' or status = $1)
            order by (status in ('neu','kontaktiert','nachgefasst')) desc, score desc, eingang desc
            limit 500`,
    werte: [ String(dat.status || '') ]
  },

  verlauf: {
    query: 'select zeitpunkt, art, text from verlauf where lead_id = $1 order by zeitpunkt desc limit 100',
    werte: [ String(dat.lead_id || '') ]
  },

  lead_speichern: {
    query: `update leads set
              status            = coalesce(nullif($2,''), status),
              verkaeufer        = coalesce(nullif($3,''), verkaeufer),
              verkaeufer_email  = coalesce(nullif($4,''), verkaeufer_email),
              notiz             = coalesce(nullif($5,''), notiz),
              sequenz           = coalesce(nullif($6,''), sequenz)
            where lead_id = $1
            returning lead_id, status, sequenz`,
    werte: [ String(dat.lead_id || ''), String(dat.status || ''), String(dat.verkaeufer || ''),
             String(dat.verkaeufer_email || ''), String(dat.notiz || ''), String(dat.sequenz || '') ]
  },

  notiz_anlegen: {
    query: `insert into verlauf (lead_id, art, text) values ($1, 'notiz', $2)
            returning id, zeitpunkt`,
    werte: [ String(dat.lead_id || ''), String(dat.text || '') ]
  },

  fahrzeuge: {
    query: `select fahrzeug_id, marke, modell, variante, erstzulassung, kilometer, kraftstoff,
                   getriebe, leistung, preis, farbe, ausstattung, status, standort
            from fahrzeuge order by status, marke, modell limit 1000`,
    werte: []
  },

  fahrzeug_speichern: {
    query: `insert into fahrzeuge (fahrzeug_id, marke, modell, variante, erstzulassung, kilometer,
              kraftstoff, getriebe, leistung, preis, farbe, ausstattung, status, standort)
            values ($1,$2,$3,$4,$5,nullif($6,'')::int,$7,$8,$9,nullif($10,'')::numeric,$11,$12,$13,$14)
            on conflict (fahrzeug_id) do update set
              marke=excluded.marke, modell=excluded.modell, variante=excluded.variante,
              erstzulassung=excluded.erstzulassung, kilometer=excluded.kilometer,
              kraftstoff=excluded.kraftstoff, getriebe=excluded.getriebe,
              leistung=excluded.leistung, preis=excluded.preis, farbe=excluded.farbe,
              ausstattung=excluded.ausstattung, status=excluded.status, standort=excluded.standort
            returning fahrzeug_id`,
    werte: [ String(dat.fahrzeug_id || ''), String(dat.marke || ''), String(dat.modell || ''),
             String(dat.variante || ''), String(dat.erstzulassung || ''), String(dat.kilometer ?? ''),
             String(dat.kraftstoff || ''), String(dat.getriebe || ''), String(dat.leistung || ''),
             String(dat.preis ?? ''), String(dat.farbe || ''), String(dat.ausstattung || ''),
             String(dat.status || 'verfuegbar'), String(dat.standort || '') ]
  },

  fahrzeug_loeschen: {
    query: 'delete from fahrzeuge where fahrzeug_id = $1 returning fahrzeug_id',
    werte: [ String(dat.fahrzeug_id || '') ]
  }
};

const gewaehlt = A[d.aktion];
if (!gewaehlt) {
  return [{ json: { erlaubt: false, fehler: 'Unbekannte Aktion: ' + d.aktion,
                    query: 'select 1 where false', sqlWerte: [] } }];
}

return [{ json: { erlaubt: true, aktion: d.aktion, query: gewaehlt.query, sqlWerte: gewaehlt.werte } }];

/* Ergebnis der Datenbank in eine saubere Antwort verpacken. */
const pruef = $('API: Anfrage prüfen').first().json;

if (!pruef.erlaubt) {
  return [{ json: { ok: false, fehler: pruef.fehler || 'Zugriff verweigert', daten: [] } }];
}

const zeilen = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);

return [{ json: {
  ok:     true,
  aktion: pruef.aktion,
  anzahl: zeilen.length,
  daten:  zeilen
}}];
